fn get_spelled_name(character: char) -> Option<&'static str> {
    Some(match character {
        '!' => "excl_",
        '#' => "hash_",
        '$' => "doll_",
        '%' => "perc_",
        '&' => "ampe_",
        '\'' => "quot_",
        '(' => "lpar_",
        ')' => "rpar_",
        '*' => "star_",
        '+' => "plus_",
        '-' => "dash_",
        '.' => "peri_",
        '/' => "slas_",
        ':' => "colo_",
        '<' => "less_",
        '=' => "equa_",
        '>' => "more_",
        '?' => "ques_",
        '@' => "atsi_",
        '[' => "lbrk_",
        '\\' => "bksl_",
        ']' => "rbrk_",
        '^' => "care_",
        '_' => "unde_",
        '|' => "vert_",
        '~' => "tild_",
        _ => return None,
    })
}

